import Image from "next/image";

interface IconProps {
  name: string;
  size?: number;
  className?: string;
}

// public/icons/*.svg 아이콘. SVG는 최적화 대상이 아니라서 unoptimized로 그대로 써요.
export default function Icon({ name, size = 20, className }: IconProps) {
  return (
    <Image
      src={`/icons/${name}.svg`}
      alt=""
      width={size}
      height={size}
      unoptimized
      className={className}
    />
  );
}
